export function 선택셔플(...값들) {
    for (let i = 값들.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [값들[i], 값들[j]] = [값들[j], 값들[i]];
    }
    return 값들;
}

export function 셔플(목록) {
    for (let i = 목록.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [목록[i], 목록[j]] = [목록[j], 목록[i]];
    }
    return 목록;
}


export function 객체생성(부모, 이름, ...스타일들) {
    const 기존엘리먼트 = document.getElementById(이름);
    if (기존엘리먼트) return window[이름];

    const 엘리먼트 = document.createElement('div');
    엘리먼트.id = 이름;

    const 지속시간 = 스타일들.find(인자 => typeof 인자 === 'number');
    if (지속시간) {
        setTimeout(() => {
            if (엘리먼트.parentNode) {
                엘리먼트.remove();
                if (window[이름]) delete window[이름];
            }
        }, 지속시간 * 1000);
    }

    const 스타일적용 = (...새스타일들) => {
        새스타일들.forEach(인자 => {
            if (typeof 인자 === 'object' && 인자 !== null) {
                if (인자.className) {
                    엘리먼트.classList.add(인자.className);
                } else {
                    Object.assign(엘리먼트.style, 인자);
                }
            } else if (typeof 인자 === 'string') {
                if (typeof 스타일 !== 'undefined' && 스타일.색상 && 스타일.색상[인자]) {
                    엘리먼트.style.color = 스타일.색상[인자];
                } else {
                    엘리먼트.style.color = 인자;
                }
            }
        });
        return window[이름];
    };

    const 프록시객체 = new Proxy(스타일적용, {
        get(target, prop) {
            const 값 = 엘리먼트[prop];
            if (typeof 값 === 'function') return 값.bind(엘리먼트);
            return 값;
        },
        set(target, prop, 값) {
            엘리먼트[prop] = 값;
            return true;
        }
    });

    window[이름] = 프록시객체;
    스타일적용(...스타일들);

    if (부모) {
        const 부모엘리먼트 = 부모.appendChild ? 부모 : document.getElementById(부모);
        if (부모엘리먼트) 부모엘리먼트.appendChild(엘리먼트);
    }

    return 프록시객체;
}

export function 인풋생성(부모, 이름, 속성들, ...스타일들) {
    const 엘리먼트 = document.createElement('input');

    엘리먼트.id = 이름;
    엘리먼트.autocomplete = 'off';
    // 3. input 전용 속성 설정 (type, placeholder, value 등)
    // 예: { type: 'text', placeholder: '이름을 입력하세요' }
    if (속성들) {
        Object.assign(엘리먼트, 속성들);
    }

    Object.assign(엘리먼트.style, ...스타일들);

    window[이름] = 엘리먼트;

    if (부모) 부모.appendChild(엘리먼트);

    return 엘리먼트;
}

export function 어썸아이콘정제(svgStr, size = 14) {
    let 정제된SVG = svgStr;

    const 크기스타일 = `style="width:${size}px; height:${size}px;"`;
    if (정제된SVG.includes('<svg')) {
        정제된SVG = 정제된SVG.replace('<svg', `<svg ${크기스타일}`);
    }

    if (정제된SVG.includes('fill=')) {
        정제된SVG = 정제된SVG.replace(/fill="[^"]*"/g, 'fill="currentColor"');
    } else {
        정제된SVG = 정제된SVG.replace(/<path/g, '<path fill="currentColor"');
    }

    return 정제된SVG;
}

export function 게임아이콘정제(svgStr, size = 14) {
    let 정제된SVG = svgStr;

    const 배경색 = "#121314";
    const 선색 = "#C9D1D9";
    // 흰색: '#FFFFFF',

    // 1. 기존 SVG 내부의 고정 크기 및 배경 제거를 위한 정규식
    // viewBox는 유지하고 width, height 스타일만 변경합니다.
    정제된SVG = 정제된SVG.replace(/style="[^"]*"/g, ''); // 기존 인라인 스타일 제거

    // 2. SVG 태그에 새로운 크기 적용
    const 기본스타일 = `style="width:${size}px; height:${size}px; background-color:${배경색}; vertical-align: middle;"`;
    정제된SVG = 정제된SVG.replace('<svg', `<svg ${기본스타일}`);

    // 3. 배경을 덮고 있는 검은색 path(#000)를 우리가 원하는 배경색으로 교체
    // 주로 첫 번째 path가 배경인 경우가 많으므로 fill="#000"을 찾아 교체합니다.
    정제된SVG = 정제된SVG.replace(/fill="#000"/g, `fill="${배경색}"`);
    정제된SVG = 정제된SVG.replace(/fill="black"/g, `fill="${배경색}"`);

    // 4. 선색 및 아이콘 색상 교체 (#fff를 선색으로)
    정제된SVG = 정제된SVG.replace(/fill="#fff"/g, `fill="${선색}"`);
    정제된SVG = 정제된SVG.replace(/fill="white"/g, `fill="${선색}"`);

    // 5. stroke 처리 (기존 로직 유지)
    if (정제된SVG.includes('stroke=')) {
        정제된SVG = 정제된SVG.replace(/stroke="[^"]*"/g, `stroke="${선색}"`);
    }

    return 정제된SVG;
}

export function n(num) {
    if (typeof num !== 'number') return num;
    if (num >= 1000000) return (num / 1000000).toFixed(1) + 'M';
    if (num >= 1000) return (num / 1000).toFixed(1) + 'K';
    return num.toLocaleString();
}

export function 숫자(num) {
    if (typeof num !== 'number') return num;
    if (num >= 1000000000000) return Number((num / 1000000000000).toFixed(1)) + '조';
    if (num >= 100000000) return (num / 100000000).toFixed(1) + '억';
    if (num >= 10000) return (num / 10000).toFixed(1) + '만';
    return num.toLocaleString();
}


