const 보상 = [
    () => {
        let 히든숙련도 = 숫자뽑기(100, 500);
        유저.현재숙련도 += 히든숙련도;
        유저.총숙련도 += 히든숙련도;
        히든보상 = `보너스 숙련도 ${히든숙련도} 획득!`;

    },
    () => {
        let 히든골드 = 100 * 숫자뽑기(유저.악마성 * 80, 유저.악마성 * 120);
        유저.현재골드 += 히든골드;
        유저.총골드 += 히든골드;
        히든보상 = `보너스 골드 ${히든골드} 획득!`;

    },
    () => {
        let 히든루비 = 숫자뽑기(10, 30);
        유저.현재루비 += 히든루비;
        유저.총루비 += 히든루비;
        히든보상 = `보너스 루비 ${히든루비} 획득!`;
    },
];


