export const 블랙공식 = (시작부터, 시작값, 현재레벨, 강화횟수 = 0, 증가율 = 1.3) => {
    if (시작부터 === 0 && 강화횟수 === 0 && 현재레벨 === 0) return 0;
    if (!강화횟수) return Math.floor(시작값 * Math.pow(증가율, 현재레벨));
    const 현재레벨비용 = 시작값 * Math.pow(증가율, 현재레벨);
    const 총비용 = 현재레벨비용 * (Math.pow(증가율, 강화횟수) - 1) / (증가율 - 1);

    return Math.floor(총비용);
};

